test:
node_scores = {'ski': 5, 'ridge': 4, '_finish': 7, '_shortcut': 2}
edges = [('ski', 'ridge', 3), ('ridge', '_finish', 2), ('ski', '_shortcut', 1)]
assert best_terminal_path('ski', node_scores, edges) == (11, ['ski', 'ridge', '_finish'])

node_scores = {'start': -2, 'ridge': 5, '_other': 9}
edges = [('start', 'ridge', 1)]
assert best_terminal_path('start', node_scores, edges) == (None, [])

try:
    best_terminal_path('start', {'start': 1, 'A': 2}, [('start', 'A', 1), ('A', 'start', 1)])
    raise AssertionError('expected cycle to be rejected')
except ValueError:
    pass

try:
    best_terminal_path('start', {'start': 1}, [('start', '_missing', 1)])
    raise AssertionError('expected unknown endpoint to be rejected')
except ValueError:
    pass

try:
    best_terminal_path('start', {'start': 1, '_end': 2}, [('start', '_end')])
    raise AssertionError('expected malformed edge to be rejected')
except ValueError:
    pass
